const row = $input.first().json;

const clientId =
  row["Client ID"] ??
  row.client_id ??
  "Not specified";

const businessName =
  row["Business Name"] ??
  row.business_name ??
  "Not specified";

const businessTimezone =
  row["Business Timezone"] ??
  row.business_timezone ??
  "";

if (!businessTimezone) {
  throw new Error(
    "The client configuration does not contain a business timezone."
  );
}

// Confirm that the stored value is a valid IANA timezone.
try {
  new Intl.DateTimeFormat("en-US", {
    timeZone: businessTimezone,
  }).format(new Date());
} catch {
  throw new Error(
    `Invalid business timezone: ${businessTimezone}`
  );
}

return [
  {
    json: {
      config_loaded: true,
      client_id: String(clientId).trim(),
      business_name: String(businessName).trim(),
      business_timezone: String(
        businessTimezone
      ).trim(),
    },
  },
];
